package com.greenocean.backend;
import com.greenocean.backend.trust.*;import com.greenocean.backend.common.exception.*;import com.greenocean.backend.professional.service.*;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.junit.jupiter.api.*;import java.util.*;import java.time.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.trust.enabled=true","greenocean.operations.enabled=true","greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa","greenocean.clinic.reputation-enabled=true","greenocean.clinic.public-reputation-enabled=true","greenocean.clinic.reputation-keys=reputation-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.reputation-current-key=reputation-qa"})@AutoConfigureMockMvc@ActiveProfiles("test")@Transactional
class PhaseQ3OperationsTest extends PhaseP4Fixtures {
 @Autowired IncidentOperations operations;@Autowired TrustCoverage coverage;@Autowired OperationsCommunications communications;@Autowired ServiceQuality quality;@Autowired RankingAssurance assurance;@Autowired OperationsAlerts alerts;
 @BeforeEach void operationalStaff(){for(var a:List.of(issuer,reviewer))for(String d:TrustAuthority.DOMAINS)role(a.id(),TrustAuthority.role(d));for(String d:TrustAuthority.DOMAINS){UUID first=coverage.schedule(reviewer.id(),reviewer.session(),d,issuer.id(),Instant.now().minusSeconds(10),Instant.now().plusSeconds(3600),10);UUID second=coverage.schedule(issuer.id(),issuer.session(),d,reviewer.id(),Instant.now().minusSeconds(10),Instant.now().plusSeconds(3600),10);coverage.acknowledge(issuer.id(),issuer.session(),first);coverage.acknowledge(reviewer.id(),reviewer.session(),second);}}
 UUID incident(String domain){return operations.detect(issuer.id(),issuer.session(),domain,"SERVICE_FAILURE","SEV2",UUID.randomUUID(),"SYNTHETIC:isolated-operations-evidence");}
 void state(UUID id,long rev,String state){operations.transition(issuer.id(),issuer.session(),id,rev,state,"SYNTHETIC:transition-evidence");}
 UUID owned(String domain){UUID id=incident(domain);state(id,1,"ACKNOWLEDGED");return id;}
 UUID proposal(UUID id,long revision,String control,String action){return operations.propose(issuer.id(),issuer.session(),id,revision,control,action,null,"SYNTHETIC:containment-evidence");}
 void approve(UUID id,UUID proposal,long revision){operations.approve(reviewer.id(),reviewer.session(),id,proposal,revision);}
 @Test@Tag("happy")void detectionRetryIsBoundAndCreatesOneTimelineEvent(){UUID key=UUID.randomUUID();UUID id=operations.detect(issuer.id(),issuer.session(),"CLINIC","DATA_EXPOSURE","SEV1",key,"SYNTHETIC:single-confidential-record");assertThat(operations.detect(issuer.id(),issuer.session(),"CLINIC","DATA_EXPOSURE","SEV1",key,"SYNTHETIC:single-confidential-record")).isEqualTo(id);assertThat(db.queryForObject("SELECT count(*) FROM operation_incident_events WHERE incident_id=?",Integer.class,id)).isEqualTo(1);assertThatThrownBy(()->operations.detect(issuer.id(),issuer.session(),"CLINIC","DATA_EXPOSURE","SEV4",key,"SYNTHETIC:single-confidential-record")).isInstanceOf(ConflictException.class);}
 @Test@Tag("malicious")void ordinaryAdministratorDoesNotInheritOperationsPurpose(){assertThatThrownBy(()->operations.queue(learner.id(),learner.session(),"CLINIC")).isInstanceOf(ForbiddenException.class);role(other.id(),"ADMIN");assertThatThrownBy(()->operations.queue(other.id(),other.session(),"CLINIC")).isInstanceOf(ForbiddenException.class);}
 @Test@Tag("malicious")void rawPrivateNarrativeAndUrlsAreNotOperationalEvidence(){for(String ref:List.of("Private clinical narrative here","https://example.test/private","JOURNAL:private body"))assertThatThrownBy(()->operations.detect(issuer.id(),issuer.session(),"CLINIC","DATA_EXPOSURE","SEV1",UUID.randomUUID(),ref)).isInstanceOf(IllegalArgumentException.class);}
 @Test@Tag("confused")void lifecycleRequiresOwnerCurrentRevisionAndDoesNotSkipRecovery(){UUID id=owned("CLINIC");assertThatThrownBy(()->state(id,1,"TRIAGED")).isInstanceOf(ConflictException.class);assertThatThrownBy(()->state(id,2,"RESOLVED")).isInstanceOf(ConflictException.class);assertThatThrownBy(()->operations.transition(reviewer.id(),reviewer.session(),id,2,"TRIAGED","SYNTHETIC:other-owner")).isInstanceOf(ForbiddenException.class);state(id,2,"TRIAGED");assertThat(operations.detail(issuer.id(),issuer.session(),id).toString()).doesNotContain("recovery_session","body_cipher","patient_id","clinical_notes");}
 @Test@Tag("confused")void missingCoverageRetainsUnassignedIncident(){UUID id=incident("CLINIC");db.update("UPDATE trust_coverage SET revoked_at=CURRENT_TIMESTAMP WHERE operator_id=?",issuer.id());assertThatThrownBy(()->state(id,1,"ACKNOWLEDGED")).isInstanceOf(ConflictException.class);assertThat(db.queryForObject("SELECT owner_id FROM operation_incidents WHERE id=?",UUID.class,id)).isNull();}
 @Test@Tag("creative")void capacityIsSharedBetweenActualIncidentsAndTrustCases(){db.update("UPDATE trust_coverage SET capacity=1 WHERE operator_id=? AND domain='CLINIC'",issuer.id());owned("CLINIC");UUID second=incident("CLINIC");assertThatThrownBy(()->state(second,1,"ACKNOWLEDGED")).isInstanceOf(ConflictException.class);}
 @Test@Tag("happy")void independentRecoveryAndFullTimelineKeepActualActors(){UUID id=owned("CLINIC");state(id,2,"TRIAGED");state(id,3,"CONTAINMENT");state(id,4,"INVESTIGATING");state(id,5,"RECOVERY_PENDING");assertThatThrownBy(()->state(id,6,"RECOVERING")).isInstanceOf(ForbiddenException.class);operations.transition(reviewer.id(),reviewer.session(),id,6,"RECOVERING","SYNTHETIC:independent-recovery-check");state(id,7,"RESOLVED");state(id,8,"POST_INCIDENT_REVIEW");state(id,9,"CLOSED");assertThat(db.queryForObject("SELECT count(*) FROM operation_incident_events WHERE incident_id=?",Integer.class,id)).isEqualTo(10);}
 @Test@Tag("malicious")void changedRecoverySessionCannotBeApproved(){UUID id=owned("CLINIC");state(id,2,"TRIAGED");state(id,3,"CONTAINMENT");state(id,4,"INVESTIGATING");state(id,5,"RECOVERY_PENDING");db.update("UPDATE user_sessions SET token_version=token_version+1 WHERE id=?",issuer.session());assertThatThrownBy(()->operations.transition(reviewer.id(),reviewer.session(),id,6,"RECOVERING","SYNTHETIC:stale-recovery")).isInstanceOf(ConflictException.class);}
 @Test@Tag("happy")void pendingControlHasNoEffectAndSecondApprovalPausesActualBooking(){UUID id=owned("CLINIC");UUID c=proposal(id,2,"CLINIC_BOOKING","PAUSE");assertThat(AdmissionContainment.paused(db,"CLINIC_BOOKING")).isFalse();assertThatThrownBy(()->operations.approve(issuer.id(),issuer.session(),id,c,2)).isInstanceOf(ForbiddenException.class);approve(id,c,2);assertThat(AdmissionContainment.paused(db,"CLINIC_BOOKING")).isTrue();assertThatThrownBy(()->commerce.book(learner.id(),new ClinicCommerce.Booking(UUID.randomUUID(),UUID.randomUUID(),1,policy,0,true))).isInstanceOf(ForbiddenException.class);assertThat(commerce.appointment(learner.id(),appointment)).containsEntry("status","CONFIRMED");assertThat(commerce.finances(learner.id(),false)).containsKey("appointments");}
 @Test@Tag("malicious")void containmentCannotBeApprovedAgainstChangedIncidentRevision(){UUID id=owned("CLINIC");UUID c=proposal(id,2,"CLINIC_BOOKING","PAUSE");state(id,2,"TRIAGED");assertThatThrownBy(()->approve(id,c,3)).isInstanceOf(ConflictException.class);assertThat(AdmissionContainment.paused(db,"CLINIC_BOOKING")).isFalse();}
 @Test@Tag("malicious")void servicePurposeDoesNotPermitFinancialOrAccountContainment(){UUID id=owned("CLINIC");assertThatThrownBy(()->proposal(id,2,"PAYMENT_CAPTURE","PAUSE")).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->operations.propose(issuer.id(),issuer.session(),id,2,"ACCOUNT_RESTRICTION","PAUSE",learner.id(),"SYNTHETIC:wrong-domain")).isInstanceOf(ForbiddenException.class);}
 @Test@Tag("confused")void pausedAdmissionCannotSilentlyExpireOrResolveBeforeIndependentRecovery(){UUID id=owned("CLINIC");UUID c=proposal(id,2,"CLINIC_BOOKING","PAUSE");approve(id,c,2);db.update("UPDATE operation_containment SET expires_at=CURRENT_TIMESTAMP-INTERVAL '1 hour' WHERE id=?",c);assertThat(AdmissionContainment.paused(db,"CLINIC_BOOKING")).isTrue();assertThatThrownBy(()->proposal(id,2,"CLINIC_BOOKING","RESUME")).isInstanceOf(ConflictException.class);state(id,2,"TRIAGED");state(id,3,"CONTAINMENT");state(id,4,"INVESTIGATING");state(id,5,"RECOVERY_PENDING");operations.transition(reviewer.id(),reviewer.session(),id,6,"RECOVERING","SYNTHETIC:recovery");assertThatThrownBy(()->state(id,7,"RESOLVED")).isInstanceOf(ConflictException.class);UUID resume=proposal(id,7,"CLINIC_BOOKING","RESUME");approve(id,resume,7);assertThat(AdmissionContainment.paused(db,"CLINIC_BOOKING")).isFalse();state(id,7,"RESOLVED");}
 @Test@Tag("happy")void approvedTargetedNoticeUsesExistingInboxAndPublicStatusHasNoEvidence(){UUID id=owned("CLINIC");UUID draft=communications.draft(issuer.id(),issuer.session(),id,2,"SERVICE_INTERRUPTION","fa",true,List.of(learner.id()));assertThat(communications.publicStatus("fa")).isEmpty();assertThatThrownBy(()->communications.approve(issuer.id(),issuer.session(),id,draft,2)).isInstanceOf(ForbiddenException.class);communications.approve(reviewer.id(),reviewer.session(),id,draft,2);String status=communications.publicStatus("fa").toString();assertThat(status).contains("موقتاً").doesNotContain(id.toString(),learner.id().toString(),"SYNTHETIC","SEV2");assertThat(db.queryForObject("SELECT count(*) FROM notifications WHERE user_id=? AND type='SYSTEM_NOTICE' AND title='وضعیت خدمت'",Integer.class,learner.id())).isEqualTo(1);assertThat(communications.queue(issuer.id(),issuer.session(),id).toString()).contains("inbox_created_count=1");assertThatThrownBy(()->communications.approve(reviewer.id(),reviewer.session(),id,draft,2)).isInstanceOf(ConflictException.class);}
 @Test@Tag("confused")void restoredStatusCannotPrecedeActualRecovery(){UUID id=owned("CLINIC");assertThatThrownBy(()->communications.draft(issuer.id(),issuer.session(),id,2,"SERVICE_RESTORED","en",true,List.of())).isInstanceOf(ConflictException.class);}
 @Test@Tag("malicious")void clinicalQualityAggregatesContainNoProtectedNarrativesOrInventedOutcomeScore(){String s=quality.summary(issuer.id(),issuer.session(),"CLINIC").toString();assertThat(s).contains("clinicalOutcomeMeasurement=false","INSUFFICIENT_EVIDENCE").doesNotContain(learner.id().toString(),author.id().toString(),"body_cipher","clinical_notes");assertThat(quality.summary(issuer.id(),issuer.session(),"ACCOUNT").toString()).contains("No journal, mood, reflection");}
 @Test@Tag("malicious")void publicRankingRequiresCurrentCohortSpecificIndependentAudit(){db.update("DELETE FROM operation_ranking_audits WHERE policy_id=?",method);assertThatThrownBy(()->reputation.rankings(learner.id(),"PSYCHOLOGIST","TEXT")).isInstanceOf(ForbiddenException.class);UUID id=assurance.propose(issuer.id(),issuer.session(),method,"PSYCHOLOGIST","TEXT",7,"SYNTHETIC:fairness-fixture-run");assertThatThrownBy(()->assurance.approve(issuer.id(),issuer.session(),id)).isInstanceOf(ForbiddenException.class);assurance.approve(reviewer.id(),reviewer.session(),id);assertThat(reputation.rankings(learner.id(),"PSYCHOLOGIST","TEXT")).containsKey("newProfessionalDiscovery");assertThatThrownBy(()->reputation.rankings(learner.id(),"PSYCHOLOGIST","AUDIO")).isInstanceOf(ForbiddenException.class);assurance.revoke(reviewer.id(),reviewer.session(),id);assertThatThrownBy(()->reputation.rankings(learner.id(),"PSYCHOLOGIST","TEXT")).isInstanceOf(ForbiddenException.class);}
 @Test@Tag("confused")void duePeriodicAuditStopsPublicRankingWithoutInventingAReview(){db.update("UPDATE operation_ranking_audits SET next_review_at=CURRENT_TIMESTAMP-INTERVAL '1 minute' WHERE policy_id=?",method);assertThatThrownBy(()->reputation.rankings(learner.id(),"PSYCHOLOGIST","TEXT")).isInstanceOf(ForbiddenException.class);}
 @Test@Tag("malicious")void routeConfigurationIsIndependentAndGeneratedAlertIsNotHumanAcknowledgement(){UUID route=alerts.route(issuer.id(),issuer.session(),"CLINIC",reviewer.id(),"PRIMARY",0,Instant.now().plusSeconds(3600));assertThatThrownBy(()->alerts.approve(issuer.id(),issuer.session(),route)).isInstanceOf(ForbiddenException.class);alerts.approve(reviewer.id(),reviewer.session(),route);alerts.acknowledgeRoute(reviewer.id(),reviewer.session(),route);UUID incident=incident("CLINIC");UUID delivery=db.queryForObject("INSERT INTO operation_alerts(incident_id,route_id) VALUES(?,?) RETURNING id",UUID.class,incident,route);assertThatThrownBy(()->alerts.acknowledge(reviewer.id(),reviewer.session(),delivery)).isInstanceOf(ConflictException.class);assertThat(alerts.routes(issuer.id(),issuer.session(),"CLINIC").toString()).contains("transport_configured=false");}
 @Test@Tag("malicious")void incidentTimelineCannotBeRewritten(){UUID id=incident("CLINIC");assertThatThrownBy(()->db.update("DELETE FROM operation_incident_events WHERE incident_id=?",id)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void classificationUsesCurrentOwnerAndExactEvidenceWithoutChangingLifecycle(){UUID id=owned("CLINIC");operations.classify(issuer.id(),issuer.session(),id,2,"DATA_EXPOSURE","SEV1","SYNTHETIC:single-record-is-serious");assertThat(db.queryForMap("SELECT state,severity,revision FROM operation_incidents WHERE id=?",id)).containsEntry("state","ACKNOWLEDGED").containsEntry("severity","SEV1").containsEntry("revision",3L);assertThatThrownBy(()->operations.classify(reviewer.id(),reviewer.session(),id,3,"SERVICE_FAILURE","SEV4","SYNTHETIC:wrong-owner")).isInstanceOf(ForbiddenException.class);}
 @Test void ownOperationalArchiveOmitsOtherStaffRecipientsAndRestrictedEvidence(){UUID id=owned("CLINIC");UUID route=alerts.route(issuer.id(),issuer.session(),"CLINIC",reviewer.id(),"PRIMARY",0,Instant.now().plusSeconds(3600));UUID draft=communications.draft(issuer.id(),issuer.session(),id,2,"CONTACT_SUPPORT","en",false,List.of(learner.id()));String own=archives.archive(issuer.id()).trustAndSecurity().toString();assertThat(own).contains(id.toString(),route.toString(),draft.toString()).doesNotContain(reviewer.id().toString(),learner.id().toString(),"isolated-operations-evidence","author_session","token_version");String member=archives.archive(learner.id()).trustAndSecurity().toString();assertThat(member).doesNotContain(id.toString(),route.toString(),draft.toString());}
 @Test void unavailableOwnerTakeoverRequiresRealCoverageAndResetsPendingRecovery(){UUID id=owned("CLINIC");state(id,2,"TRIAGED");state(id,3,"CONTAINMENT");state(id,4,"INVESTIGATING");state(id,5,"RECOVERY_PENDING");assertThatThrownBy(()->operations.claimUnavailable(reviewer.id(),reviewer.session(),id,6,"SYNTHETIC:premature-takeover")).isInstanceOf(ConflictException.class);db.update("UPDATE trust_coverage SET revoked_at=CURRENT_TIMESTAMP WHERE operator_id=?",issuer.id());operations.claimUnavailable(reviewer.id(),reviewer.session(),id,6,"SYNTHETIC:actual-coverage-gap-takeover");var r=db.queryForMap("SELECT owner_id,state,recovery_author,revision FROM operation_incidents WHERE id=?",id);assertThat(r).containsEntry("owner_id",reviewer.id()).containsEntry("state","INVESTIGATING").containsEntry("recovery_author",null).containsEntry("revision",7L);}
 @Test@Tag("malicious")void recoveringOneIncidentCannotLiftAnotherIncidentsAdmissionHold(){UUID first=owned("CLINIC"),second=owned("CLINIC");approve(first,proposal(first,2,"CLINIC_BOOKING","PAUSE"),2);approve(second,proposal(second,2,"CLINIC_BOOKING","PAUSE"),2);state(first,2,"TRIAGED");state(first,3,"CONTAINMENT");state(first,4,"INVESTIGATING");state(first,5,"RECOVERY_PENDING");operations.transition(reviewer.id(),reviewer.session(),first,6,"RECOVERING","SYNTHETIC:independent-first-recovery");approve(first,proposal(first,7,"CLINIC_BOOKING","RESUME"),7);assertThat(AdmissionContainment.paused(db,"CLINIC_BOOKING")).isTrue();state(first,7,"RESOLVED");assertThatThrownBy(()->commerce.book(learner.id(),new ClinicCommerce.Booking(UUID.randomUUID(),UUID.randomUUID(),1,policy,0,true))).isInstanceOf(ForbiddenException.class);}
}
